# region: shape
def shape(raw):
    return [len(tok.strip()) for tok in raw if tok.strip()]

# region: intake
def intake(xs):
    acc = 0
    out = []
    for v in xs:
        acc = acc + v
        out.append(acc)
    return out

# region: fold
def fold(xs):
    acc = 0
    out = []
    for v in xs[:-1]:
        acc = acc + v
        out.append(acc)
    return out

# region: emit
def emit(xs):
    return {'n': len(xs), 'total': sum(xs)}

# region: render
def render(summary, bar=2):
    out = dict(summary)
    n = summary.get('n', 0)
    out['ratio'] = round(n / bar, 3) if bar else 0.0
    return out

# region: run
def run(raw):
    return render(emit(fold(intake(shape(raw)))))

